      ]
    },
    {
      "id": 2,
      "description": "Create a utility function that accepts the current filtered activity data and generates a valid CSV string with proper formatting (headers, escaping, UTF-8 encoding). Include columns: timestamp, actor, action, card title.",
      "addressesRequirements": ["ER3", "IR2"],
      "files": [
        "src/utils/csvExport.ts"
      ]
    },
    {
      "id": 3,
      "description": "Implement click handler for the export button that retrieves the current filtered activity log data (respecting active date-range and other filters), generates the CSV using the utility function, and triggers a browser download with a timestamped filename.",
      "addressesRequirements": ["ER2", "IR1", "IR4"],
      "files": [
        "src/components/ActivityLog/ActivityLog.tsx",
        "src/components/ActivityLog/ActivityLogHeader.tsx"
      ]
    },
    {
      "id": 4,
      "description": "Add tooltip to the disabled export button that appears when the log is empty, informing users why the button is unavailable.",
      "addressesRequirements": ["ER4"],
      "files": [
        "src/components/ActivityLog/ActivityLogHeader.tsx"
      ]
    },
    {
      "id": 5,
      "description": "Test the export functionality with various filter states, verify CSV file format is correct, and ensure the button state correctly reflects log content.",
      "addressesRequirements": ["ER1", "ER2", "ER3", "ER4", "IR1", "IR2"],
      "files": []
    }
  ],
  "testStrategy": [
    "Unit tests for csvExport utility: verify correct CSV formatting with various input data (special characters, quotes, newlines, empty values)",
    "Unit tests for export button state: verify button is disabled when log is empty and enabled when log has data",
    "Integration tests: export with active date-range filter and verify exported CSV contains only filtered rows",
    "Integration tests: export with multiple filters active and verify all filters are respected in output",
    "Manual test: download CSV file and verify it opens correctly in Excel/Google Sheets and contains expected columns and data",
    "Manual test: verify disabled tooltip displays appropriately when log is empty",
    "Edge case testing: export with very large datasets to ensure performance is acceptable"
  ],
  "risks": [
    {
      "description": "Ambiguity on whether to export all historical rows in date range or only visible paginated rows could lead to user confusion or data completeness issues",
      "mitigation": "Default to exporting all rows matching active filters regardless of pagination. Document this behavior and provide warning if export size is large. If pagination should limit export, this should be clarified with product owner before implementation."
    },
    {
      "description": "Unknown filters beyond date-range might not be properly respected in export, leading to inconsistency with displayed data",
      "mitigation": "Build the export to use the same filtering logic as the display layer. Apply all active filter state to the export query. Add filter indicator in exported filename or metadata."
    },
    {
      "description": "No defined maximum row limit could result in very large CSV files that cause performance issues or browser memory problems",
      "mitigation": "Implement a reasonable default limit (e.g., 10,000 rows) with user warning if approaching limit. Document this in UI tooltip. Consider pagination of exports for very large datasets."
    },
    {
      "description": "Special characters in card titles, actor names, or actions might not be properly escaped, corrupting the CSV",
      "mitigation": "Use robust CSV library or well-tested utility function with comprehensive escaping. Include unit tests for edge cases (quotes, commas, newlines, non-ASCII characters)."
    },
    {
      "description": "Filename collision or unclear naming could make it difficult for users to identify which export corresponds to which date/filter",
      "mitigation": "Use timestamped filenames (e.g., 'activity-log-2024-01-15-14-30-45.csv') and consider including filter summary in filename or first row as metadata."
    }
  ],
  "outOfScope": [
    "Implementing email-based export or scheduled reports",
    "Supporting export formats other than CSV (JSON, Excel, etc.)",
    "Adding export analytics or audit logging of who exported what data",
    "Implementing row-level access controls on exported data (assume current filter respects user permissions)",
    "Creating custom export templates or column selection UI"
  ]
}
